export const VENDOR_STATUS = {
  PENDING: 'pending',
  ACTIVE: 'active',
  SUSPENDED: 'suspended',
  REJECTED: 'rejected',
};

export const VENDOR_STATUSES = Object.values(VENDOR_STATUS);

export const VENDOR_ASSIGNABLE_STATUSES = [
  VENDOR_STATUS.ACTIVE,
  VENDOR_STATUS.SUSPENDED,
  VENDOR_STATUS.REJECTED,
];

export const VENDOR_TRANSITIONS = {
  [VENDOR_STATUS.PENDING]: [VENDOR_STATUS.ACTIVE, VENDOR_STATUS.REJECTED],
  [VENDOR_STATUS.ACTIVE]: [VENDOR_STATUS.SUSPENDED],
  [VENDOR_STATUS.SUSPENDED]: [VENDOR_STATUS.ACTIVE],
  [VENDOR_STATUS.REJECTED]: [],
};